<script>
'use strict';
const cv=document.getElementById('bowCanvas'),g=cv.getContext('2d');
const W=960,H=540,GROUND=470,ARCHER_X=120,ARCHER_Y=392,GRAV=820,MAX_PULL=150,GOAL=400,MAX_LIVES=5;
const FONT='"Silkscreen","Courier New",monospace';
const COLORS=['#e8433f','#f6a821','#3fa7e8','#58c463','#c05fd8'];
let state='menu',score=0,lives=MAX_LIVES,best=+(localStorage.getItem('balloonBowmanBest')||0);
let arrows=[],balloons=[],bits=[],popups=[],clouds=[];
let drag=null,mouse={x:500,y:300},shake=0,hitStop=0,spawnT=0,playT=0,flash=0,shots=0,hits=0,lastTick=0,recoil=0,stateT=0;
for(let i=0;i<6;i++)clouds.push({x:Math.random()*W,y:30+Math.random()*170,s:.6+Math.random()*.9,v:4+Math.random()*8});

/* ---------- audio: all synthesized, no assets ---------- */
let ac=null,noiseBuf=null,master=null;
function audioInit(){
  if(ac){if(ac.state==='suspended')ac.resume();return;}
  try{
    ac=new (window.AudioContext||window.webkitAudioContext)();
    master=ac.createGain();master.gain.value=.55;
    const comp=ac.createDynamicsCompressor();master.connect(comp);comp.connect(ac.destination);
    noiseBuf=ac.createBuffer(1,ac.sampleRate,ac.sampleRate);
    const d=noiseBuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
  }catch(e){ac=null;}
}
function tone(type,f0,f1,dur,vol,delay){
  if(!ac)return;const t=ac.currentTime+(delay||0),o=ac.createOscillator(),v=ac.createGain();
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);
  v.gain.setValueAtTime(0,t);v.gain.linearRampToValueAtTime(vol,t+.005);v.gain.exponentialRampToValueAtTime(.0001,t+dur);
  o.connect(v);v.connect(master);o.start(t);o.stop(t+dur+.02);
}
function noise(f0,f1,q,dur,vol,delay,type){
  if(!ac)return;const t=ac.currentTime+(delay||0),s=ac.createBufferSource(),f=ac.createBiquadFilter(),v=ac.createGain();
  s.buffer=noiseBuf;s.loop=true;f.type=type||'bandpass';f.Q.value=q;
  f.frequency.setValueAtTime(f0,t);f.frequency.exponentialRampToValueAtTime(f1,t+dur);
  v.gain.setValueAtTime(vol,t);v.gain.exponentialRampToValueAtTime(.0001,t+dur);
  s.connect(f);f.connect(v);v.connect(master);s.start(t,Math.random()*.5);s.stop(t+dur+.02);
}
const sfx={
  creak(p){tone('triangle',90+p*260,80+p*240,.05,.10);noise(900+p*1500,700,6,.04,.06);},
  twang(p){tone('sawtooth',150+p*130,60,.28,.20+p*.12);tone('triangle',300+p*260,120,.18,.14);noise(500,3200,1.2,.22+p*.12,.14+p*.2);},
  pop(n){const k=Math.pow(1.122,Math.min(n,12));noise(2600,500,.7,.11,.75,0,'highpass');noise(1400,300,1.5,.09,.5);
    tone('square',240*k,90,.09,.22);tone('sine',700*k,1400*k,.12,.16,.03);},
  gold(){[880,1175,1568,2093].forEach((f,i)=>tone('triangle',f,f,.2,.16,i*.055));},
  thud(){tone('sine',130,50,.12,.3);noise(400,150,1,.07,.2,0,'lowpass');},
  escape(){tone('sawtooth',420,140,.38,.16);tone('square',210,70,.38,.10,.02);},
  start(){[392,523,659,784].forEach((f,i)=>tone('square',f,f,.14,.12,i*.08));},
  win(){[523,659,784,1047,784,1047,1319].forEach((f,i)=>tone('square',f,f,.2,.13,i*.11));},
  lose(){[392,330,262,196].forEach((f,i)=>tone('sawtooth',f,f*.94,.3,.13,i*.18));}
};

